import random
import ipaddress
import string

# This generator produces a NUL-terminated C string buffer intended to be used
# by FUZZ_PARAM_STR in the gpsmm::gpsmm(host, port) fuzzer stub. It aims to
# generate valid and interesting hostnames or ports accepted by libgps/gpsd.
# The buffer contains two NUL-terminated strings concatenated: "host\0port\0".
# The fuzzer can split them for FUZZ_PARAM_STR calls in order.
# Size is kept under 4096 bytes.

SPECIAL_HOSTS = [
    "localhost",
    "::1",
    "127.0.0.1",
    "[::1]",
    "0.0.0.0",
    "[2001:db8::1]",  # documentation IPv6
    "gpsd",           # possible mDNS/hostname
    "socket://localhost",
    "file:///dev/ttyUSB0",  # some builds accept device URIs or device strings
]

COMMON_HOSTS = [
    "example.com",
    "gps.example.com",
    "test.local",
    "router.lan",
]

SPECIAL_PORTS = [
    "2947",        # default gpsd port
    "0",           # edge numeric
    "65535",       # max valid TCP/UDP port
    "gpsd",        # service name (getservbyname)
]

SERVICE_PORTS = [
    "http", "https", "telnet", "ssh", "ntp", "domain"
]


def rand_ipv4(rng: random.Random) -> str:
    # Prefer valid unicast, sometimes loopback or multicast for variance
    choice = rng.random()
    if choice < 0.2:
        return str(ipaddress.IPv4Address(0x7F000001))  # 127.0.0.1
    elif choice < 0.4:
        # documentation prefix 192.0.2.0/24
        return f"192.0.2.{rng.randint(1,254)}"
    elif choice < 0.6:
        return f"198.51.100.{rng.randint(1,254)}"  # TEST-NET-2
    elif choice < 0.8:
        return f"203.0.113.{rng.randint(1,254)}"   # TEST-NET-3
    else:
        return f"{rng.randint(1,223)}.{rng.randint(0,255)}.{rng.randint(0,255)}.{rng.randint(1,254)}"


def rand_ipv6(rng: random.Random, bracketed: bool = True) -> str:
    # Use documentation prefix 2001:db8::/32, sometimes loopback
    if rng.random() < 0.2:
        s = "::1"
    else:
        parts = [
            0x2001, 0x0DB8,
            rng.randrange(0, 0x10000),
            rng.randrange(0, 0x10000),
            rng.randrange(0, 0x10000),
            rng.randrange(0, 0x10000),
            rng.randrange(0, 0x10000),
            rng.randrange(0, 0x10000),
        ]
        s = ":".join(f"{p:x}" for p in parts)
    if bracketed:
        return f"[{s}]"
    return s


def rand_hostname_label(rng: random.Random, min_len=1, max_len=10) -> str:
    # RFC 1035 compliant-ish: letters, digits, hyphen, not starting/ending with hyphen
    length = rng.randint(min_len, max_len)
    if length == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    middle_len = length - 2
    start = rng.choice(string.ascii_lowercase)
    middle_chars = string.ascii_lowercase + string.digits + "-"
    middle = "".join(rng.choice(middle_chars) for _ in range(middle_len)) if middle_len > 0 else ""
    end = rng.choice(string.ascii_lowercase + string.digits)
    return start + middle + end


def rand_hostname(rng: random.Random) -> str:
    # Generate 2-4 labels plus a TLD
    labels = [rand_hostname_label(rng) for _ in range(rng.randint(1, 3))]
    tlds = ["com", "net", "org", "io", "local", "lan"]
    labels.append(rng.choice(tlds))
    return ".".join(labels)


def choose_host(rng: random.Random) -> str:
    p = rng.random()
    if p < 0.15:
        return rng.choice(SPECIAL_HOSTS)
    elif p < 0.35:
        return rng.choice(COMMON_HOSTS)
    elif p < 0.55:
        return rand_ipv4(rng)
    elif p < 0.8:
        # IPv6, sometimes without brackets (some contexts accept raw IPv6)
        return rand_ipv6(rng, bracketed=rng.random() < 0.7)
    else:
        return rand_hostname(rng)


def choose_port(rng: random.Random) -> str:
    p = rng.random()
    if p < 0.4:
        return rng.choice(SPECIAL_PORTS)
    elif p < 0.55:
        return rng.choice(SERVICE_PORTS)
    elif p < 0.9:
        # numeric in valid port range
        return str(rng.randint(1, 65535))
    else:
        # leave empty string occasionally to exercise defaults/failure paths
        return ""


def maybe_embed_credentials(rng: random.Random, host: str) -> str:
    # Occasionally embed userinfo like user:pass@host for URL-like forms used by some apps
    if rng.random() < 0.1:
        user = rand_hostname_label(rng, 3, 8)
        pw = rand_hostname_label(rng, 3, 8)
        return f"{user}:{pw}@{host}"
    return host


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    host = choose_host(rng)
    host = maybe_embed_credentials(rng, host)

    # Occasionally prefix with schemes recognized by some gpsd utilities (not mandatory)
    if rng.random() < 0.1:
        scheme = rng.choice(["tcp://", "udp://", "socket://", "file://"])
        host = scheme + host

    port = choose_port(rng)

    # Build buffer: host\0port\0
    # Ensure total size <= 4096 bytes
    max_each = 2000
    host_b = host.encode('utf-8')[:max_each]
    port_b = port.encode('utf-8')[:max_each]

    buf = host_b + b"\x00" + port_b + b"\x00"
    if len(buf) > 4096:
        buf = buf[:4095] + b"\x00"
    return buf

